fn main() {
    let mut numbers = vec![1, 2, 3];

    for n in numbers.iter() {
        println!("read {n}");
    }

    for n in numbers.iter_mut() {
        *n *= 10;
    }
    println!("{:?}", numbers);

    for n in numbers.into_iter() {
        println!("owned {n}");
    }
    // numbers has been moved into the loop and can't be used here
}

struct Countdown {
    n: u32,
}

impl Iterator for Countdown {
    type Item = u32;

    fn next(&mut self) -> Option<u32> {
        if self.n == 0 {
            None
        } else {
            let current = self.n;
            self.n -= 1;
            Some(current)
        }
    }
}

fn main() {
    for x in (Countdown { n: 3 }) {
        println!("{x}");
    }

    // writing next gave us more methods for free, such as sum
    let total: u32 = Countdown { n: 4 }.sum();   // 4 + 3 + 2 + 1
    println!("total {total}");
}

