struct Counter {
    current: u32,
    max: u32,
}

impl Iterator for Counter {
    type Item = u32;

    fn next(&mut self) -> Option<u32> {
        if self.current > self.max {
            None
        } else {
            let value = self.current;
            self.current += 1;
            Some(value)
        }
    }
}

fn main() {
    let counter = Counter { current: 1, max: 4 };
    for n in counter {
        println!("{n}");
    }
}
